	"os"
)

func main() {
	var c [3][4]byte
	reader := bufio.NewReader(os.Stdin)

	for i := 0; i < 3; i++ {
		for j := 0; j <= 3; j++ {
			b, err := reader.ReadByte()
			if err != nil {
				b = 0
			}
			c[i][j] = b
		}
	}

	if c[0][0] == c[2][2] &&
		c[0][1] == c[2][1] &&
		c[0][2] == c[2][0] &&
		c[1][0] == c[1][2] {
