	} else {
		fmt.Println("NO")
	}
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	var grid [3]string
	for i := 0; i < 3; i++ {
		if scanner.Scan() {
			grid[i] = scanner.Text()
		}
	}

	// Ensure we have at least 3 characters per row for the checks
	// The C code reads 4 chars per row (3 data + newline usually), but only uses indices 0,1,2.
	// We assume input lines have at least 3 characters.
	if len(grid[0]) < 3 || len(grid[1]) < 3 || len(grid[2]) < 3 {
		fmt.Println("NO")
		return
	}

	// Checks for 180-degree rotational symmetry (point reflection) on the 3x3 grid
	// (0,0)<->(2,2), (0,1)<->(2,1), (0,2)<->(2,0)
	// (1,0)<->(1,2), (1,1)<->(1,1)
	ok := grid[0][0] == grid[2][2] &&
		grid[0][1] == grid[2][1] &&
		grid[0][2] == grid[2][0] &&
		grid[1][0] == grid[1][2] &&
		grid[1][1] == grid[1][1] && // Always true
		grid[1][2] == grid[1][0]   // Redundant with grid[1][0] == grid[1][2]

	if ok {
		fmt.Println("YES")
	} else {
		fmt.Println("NO")
	}
}

